// Render the agent's structured output into the plain-text report (default).
const base = $('Parse Payload').item.json;
const data = $json.output || {};
const lines = ['EOD Report  ' + (base.date || ''), ''];
for (const b of (data.buildings || [])) {
  lines.push(String(b.building || '').toUpperCase());
  lines.push('');
  for (const w of (b.wings || [])) {
    lines.push('  ' + (w.wing || ''));
    for (const bul of (w.bullets || [])) lines.push('    • ' + bul);
    lines.push('');
  }
}
const text = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
return [{ json: {
  report_text: text,
  report_data: data,
  date: base.date || '',
  building_names: base.building_names || [],
  email_enabled: base.email_enabled === true
} }];

// Email-only: render the SAME structured data into HTML.
const data = $json.report_data || {};
const date = $json.date || '';
const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
let html = `<div style='font-family:Segoe UI,Arial,sans-serif;color:#1f2937;max-width:720px;margin:0 auto;padding:8px;'>`;
html += `<h1 style='font-size:20px;border-bottom:2px solid #0ea5e9;padding-bottom:8px;margin:0 0 10px;'>EOD Report — ${esc(date)}</h1>`;
for (const b of (data.buildings || [])) {
  html += `<h2 style='font-size:17px;color:#0b1324;margin:20px 0 6px;'>${esc(b.building)}</h2>`;
  for (const w of (b.wings || [])) {
    html += `<h3 style='font-size:14px;color:#0369a1;margin:12px 0 4px;'>${esc(w.wing)}</h3>`;
    html += `<ul style='margin:0 0 10px;padding-left:20px;line-height:1.5;'>`;
    for (const bul of (w.bullets || [])) html += `<li>${esc(bul)}</li>`;
    html += `</ul>`;
  }
}
html += `</div>`;
return [{ json: { ...$json, report_html: html } }];
